class UmhParametricProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    const opts = (options && options.processorOptions) || {};
    this.targetRate = opts.envelopeRate || 20000;
    this.gainDb = opts.gainDb || 0;
    this.lowPassFrequency = opts.lowPass || 8000;
    this.modulation = Math.max(10, Math.min(95, opts.modulation || 60)) / 100;
    this.eqGains = Array.isArray(opts.eqGains) ? opts.eqGains.slice(0, 8) : [0, 0, 0, 0, 0, 0, 0, 0];
    this.ctxRate = sampleRate;
    this.chunkSize = opts.chunkSize || 256;
    this.chunk = new Uint8Array(this.chunkSize);
    this.chunkFill = 0;
    this.meter = 0;
    this.chunkPeak = 0;
    this.meterAttack = 1 - Math.exp(-1 / (this.targetRate * 0.010));
    this.meterRelease = 1 - Math.exp(-1 / (this.targetRate * 0.250));
    this.gain = Math.pow(10, this.gainDb / 20);
    this.resamplePhase = 0;
    this.prevInput = 0;
    this.inputLowPass = 0;
    this.inputLowCoefficient = 1 - Math.exp((-2 * Math.PI * Math.min(this.lowPassFrequency, 0.45 * this.targetRate)) / this.ctxRate);
    this.dcPole = Math.exp((-2 * Math.PI * 20) / this.targetRate);
    this.dcState = 0;
    this.dcPrev = 0;
    this.eqSections = [];
    this.lowSections = [];
    this.buildEq();
    this.buildLowPass();
    this.lookaheadSize = Math.max(1, Math.round(this.targetRate * 0.005));
    this.lookahead = new Float32Array(this.lookaheadSize);
    this.lookaheadPos = 0;
    this.limiterGain = 1;
    this.limiterRelease = 1 - Math.exp(-1 / (this.targetRate * 0.050));
    this.activity = 0;
    this.activityAttack = 1 - Math.exp(-1 / (this.targetRate * 0.00025));
    this.activityRelease = 1 - Math.exp(-1 / (this.targetRate * 0.005));
    this.quantizationError = 0;
    this.silenceThreshold = 0.003;
    this.port.onmessage = (event) => {
      const data = event.data || {};
      if (data.type === 'config') this.applyConfig(data);
      else if (data.type === 'reset') this.reset();
    };
  }

  applyConfig(data) {
    if (typeof data.gainDb === 'number') {
      this.gainDb = data.gainDb;
      this.gain = Math.pow(10, this.gainDb / 20);
    }
    if (typeof data.modulation === 'number') {
      this.modulation = Math.max(10, Math.min(95, data.modulation)) / 100;
    }
    if (typeof data.lowPass === 'number') {
      this.lowPassFrequency = data.lowPass;
      this.inputLowCoefficient = 1 - Math.exp((-2 * Math.PI * Math.min(this.lowPassFrequency, 0.45 * this.targetRate)) / this.ctxRate);
      this.buildLowPass();
    }
    if (Array.isArray(data.eqGains)) {
      this.eqGains = data.eqGains.slice(0, 8);
      this.buildEq();
    }
  }

  reset() {
    this.dcState = 0;
    this.dcPrev = 0;
    for (const section of this.eqSections) section.reset();
    for (const section of this.lowSections) section.reset();
    this.lookahead.fill(0);
    this.lookaheadPos = 0;
    this.limiterGain = 1;
    this.activity = 0;
    this.quantizationError = 0;
    this.prevInput = 0;
    this.inputLowPass = 0;
    this.resamplePhase = 0;
  }

  buildEq() {
    const centers = [125, 250, 500, 1000, 2000, 4000, 8000, 12000];
    this.eqSections = centers.map((frequency, index) => new BiquadSection('peaking', frequency, this.eqGains[index] || 0, 1.0, this.targetRate));
  }

  buildLowPass() {
    const qs = [0.5097956, 0.6013449, 0.8999762, 2.5629156];
    const frequency = Math.min(this.lowPassFrequency, this.targetRate * 0.45);
    this.lowSections = qs.map((q) => new BiquadSection('lowpass', frequency, 0, q, this.targetRate));
  }

  process(inputs, outputs) {
    const inputChannels = inputs && inputs[0] ? inputs[0] : [];
    const outputChannels = outputs && outputs[0] ? outputs[0] : [];
    const length = Math.max(inputChannels[0] ? inputChannels[0].length : 0, outputChannels[0] ? outputChannels[0].length : 128);
    const input = inputChannels[0];
    const output = outputChannels[0];
    for (let i = 0; i < length; i++) {
      let sample = 0;
      if (input && input.length > 0) {
        sample = input[i] || 0;
        if (inputChannels.length > 1) {
          for (let channel = 1; channel < inputChannels.length; channel++) {
            sample += inputChannels[channel][i] || 0;
          }
          sample /= inputChannels.length;
        }
      }
      sample = Math.max(-1, Math.min(1, sample));
      this.inputLowPass += (sample - this.inputLowPass) * this.inputLowCoefficient;
      const filtered = this.inputLowPass;
      this.resamplePhase += this.targetRate;
      while (this.resamplePhase >= this.ctxRate) {
        this.resamplePhase -= this.ctxRate;
        const alpha = this.resamplePhase / this.ctxRate;
        const resampled = this.prevInput + (filtered - this.prevInput) * alpha;
        this.processTargetSample(resampled);
      }
      this.prevInput = filtered;
      if (output) output[i] = 0;
    }
    return true;
  }

  processTargetSample(input) {
    const dc = input - this.dcPrev + this.dcPole * this.dcState;
    this.dcPrev = input;
    this.dcState = dc;
    let value = dc * this.gain;
    for (const section of this.eqSections) value = section.process(value);
    for (const section of this.lowSections) value = section.process(value);

    const delayed = this.lookahead[this.lookaheadPos];
    this.lookahead[this.lookaheadPos] = value;
    this.lookaheadPos = (this.lookaheadPos + 1) % this.lookaheadSize;
    let peak = Math.abs(delayed);
    for (let i = 0; i < this.lookaheadSize; i++) {
      const candidate = Math.abs(this.lookahead[i]);
      if (candidate > peak) peak = candidate;
    }
    const desired = peak > 0.98 ? 0.98 / peak : 1;
    this.limiterGain = desired < this.limiterGain
      ? desired
      : this.limiterGain + (desired - this.limiterGain) * this.limiterRelease;
    const sample = Math.max(-0.98, Math.min(0.98, delayed * this.limiterGain));

    const absolute = Math.abs(sample);
    this.activity += (absolute - this.activity) * (absolute > this.activity ? this.activityAttack : this.activityRelease);
    if (this.activity < 0.0000003) this.activity = 0;
    const gate = Math.max(0, Math.min(1, (this.activity - this.silenceThreshold) / this.silenceThreshold));
    let level = 0;
    if (gate > 0) {
      const field = gate * Math.sqrt(Math.max(0, Math.min(1, (1 + this.modulation * sample) / (1 + this.modulation))));
      const idealTicks = (Math.asin(Math.max(0, Math.min(1, field))) / Math.PI) * 256;
      if (idealTicks >= 0.5) {
        const shaped = idealTicks + this.quantizationError;
        let ticks = Math.round(shaped);
        if (ticks < 0) ticks = 0;
        if (ticks > 128) ticks = 128;
        this.quantizationError = (shaped - ticks) * 0.6;
        level = ticks;
      } else {
        this.quantizationError = 0;
      }
    }
    this.meter += (gate - this.meter) * (gate > this.meter ? this.meterAttack : this.meterRelease);
    if (this.meter > this.chunkPeak) this.chunkPeak = this.meter;
    this.pushLevel(level);
  }

  pushLevel(level) {
    this.chunk[this.chunkFill++] = level;
    if (this.chunkFill >= this.chunkSize) {
      const completed = this.chunk;
      this.port.postMessage({ type: 'levels', data: completed.buffer, meter: this.chunkPeak }, [completed.buffer]);
      this.chunk = new Uint8Array(this.chunkSize);
      this.chunkFill = 0;
      this.chunkPeak = 0;
    }
  }
}

class BiquadSection {
  constructor(type, frequency, gainDb, q, sampleRate) {
    this.x1 = 0;
    this.x2 = 0;
    this.y1 = 0;
    this.y2 = 0;
    this.update(type, frequency, gainDb, q, sampleRate);
  }

  update(type, frequency, gainDb, q, sampleRate) {
    frequency = Math.max(10, Math.min(frequency, sampleRate * 0.45));
    const w0 = (2 * Math.PI * frequency) / sampleRate;
    const cos = Math.cos(w0);
    if (type === 'lowpass') {
      const alpha = Math.sin(w0) / (2 * Math.max(0.01, q));
      const a0 = 1 + alpha;
      this.b0 = ((1 - cos) * 0.5) / a0;
      this.b1 = (1 - cos) / a0;
      this.b2 = this.b0;
      this.a1 = (-2 * cos) / a0;
      this.a2 = (1 - alpha) / a0;
      return;
    }
    const a = Math.pow(10, gainDb / 40);
    const alpha = Math.sin(w0) / (2 * Math.max(0.01, q));
    const b0 = 1 + alpha * a;
    const b1 = -2 * cos;
    const b2 = 1 - alpha * a;
    const a0 = 1 + alpha / a;
    const a1 = -2 * cos;
    const a2 = 1 - alpha / a;
    this.b0 = b0 / a0;
    this.b1 = b1 / a0;
    this.b2 = b2 / a0;
    this.a1 = a1 / a0;
    this.a2 = a2 / a0;
  }

  process(input) {
    const output = this.b0 * input + this.b1 * this.x1 + this.b2 * this.x2 - this.a1 * this.y1 - this.a2 * this.y2;
    this.x2 = this.x1;
    this.x1 = input;
    this.y2 = this.y1;
    this.y1 = output;
    return output;
  }

  reset() {
    this.x1 = 0;
    this.x2 = 0;
    this.y1 = 0;
    this.y2 = 0;
  }
}

